import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadAcData(){const e=readFileSync(resolve(__dirname,"../../frontend/ashoka-chakra-explorer/ac-data.js"),"utf-8");return new Function(e+"\nreturn { AC_INFO, AC_HISTORY, AC_ELIGIBILITY, AC_MEDAL_DESIGN, AC_HEROISM_TYPES, AC_HEROES, AC_TIMELINE, AC_FACTS };")()}describe("Ashoka Chakra Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadAcData()}),describe("AC_INFO metadata",()=>{it("contains correct award metadata and statistics",()=>{expect(e.AC_INFO.id).toBe("ashoka-chakra"),expect(e.AC_INFO.totalRecipients).toBe(90),expect(e.AC_INFO.symbolism).toContain("Ashoka"),expect(Array.isArray(e.AC_INFO.quickStats)).toBe(!0),expect(e.AC_INFO.quickStats.length).toBe(6)})}),describe("AC_HISTORY & MEDAL_DESIGN",()=>{it("contains history, peacetime significance, and medal specs",()=>{expect(e.AC_HISTORY.overview).toBeDefined(),expect(e.AC_HISTORY.peacetimeSignificance).toBeDefined(),expect(e.AC_MEDAL_DESIGN.obverse).toContain("Ashoka Chakra"),expect(e.AC_MEDAL_DESIGN.ribbon).toContain("Green")})}),describe("AC_HEROES catalog",()=>{it("contains iconic recipients including Neerja Bhanot, Sandeep Unnikrishnan, and Kamlesh Kumari",()=>{expect(Array.isArray(e.AC_HEROES)).toBe(!0),expect(e.AC_HEROES.length).toBeGreaterThanOrEqual(6);const t=e.AC_HEROES.find(e=>"neerja-bhanot"===e.id),a=e.AC_HEROES.find(e=>"sandeep-unnikrishnan"===e.id),n=e.AC_HEROES.find(e=>"kamlesh-kumari"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined(),expect(n).toBeDefined(),expect(t.famousWords).toContain("Do your duty"),expect(a.famousWords).toContain("Do not come up")})}),describe("AC_TIMELINE & FACTS",()=>{it("has timeline milestones and interesting facts",()=>{expect(Array.isArray(e.AC_TIMELINE)).toBe(!0),expect(e.AC_TIMELINE.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(e.AC_FACTS)).toBe(!0),expect(e.AC_FACTS.length).toBe(6)})}),describe("Landing Page Integration",()=>{it("is integrated into awards-of-india-explorer landing page",()=>{const e=readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer/index.html"),"utf-8");expect(e).toContain("../ashoka-chakra-explorer/index.html"),expect(e).toContain("Ashoka Chakra")})})});